<?php declare(strict_types=1);
$billingActor=$settings->actor();if($billingActor['members_access']==='none')return;
$billing=new \Kulturhus\Verein\CatalogBilling($db,(string)$_SESSION['actor']);$billingError='';$review=[];$saved=[];
$failed=input($_POST,'action')==='catalog-billing-book';$source=$failed?$_POST:$_GET;
$day=input($source,'billing_date',date('Y-m-d'));$due=input($source,'billing_due',\Kulturhus\Verein\Finance::contributionDueDate(date('Y-m-d')));$mode=input($source,'billing_mode','full');$priceDay=input($source,'billing_day');$key=input($source,'billing_key',bin2hex(random_bytes(16)));$ids=[];$oldItems=[];$page=null;
try{
 $billing->actor();
 if($failed){$oldItems=\Kulturhus\Verein\CatalogBilling::items(is_array($_POST['billing_items']??null)?$_POST['billing_items']:[],true);$ids=array_column($oldItems,'assignment_id');}
 elseif(isset($_GET['billing_assignments'])){if(!is_array($_GET['billing_assignments']))throw new DomainException('Tarifzuweisungen auswählen.');$ids=\Kulturhus\Verein\CatalogBilling::items($_GET['billing_assignments']);}
 elseif(isset($_GET['billing_review']))throw new DomainException('Mindestens eine Tarifzuweisung auswählen.');
 if($ids){$review=$billing->review($ids,$day,$mode,$priceDay?:null);foreach($review as$row)if(($row['kind']==='service')!==($tab==='services'))throw new DomainException('Tarife im passenden Katalog auswählen.');}
 elseif(isset($_GET['billing_key'])){$q=$db->prepare('SELECT entry_id,quote_json FROM native_catalog_charges WHERE club_id=? AND batch_key=? ORDER BY ordinal');$q->execute([$billingActor['club_id'],$key]);$saved=$q->fetchAll(PDO::FETCH_ASSOC);if(!$saved)throw new DomainException('Eigene gespeicherte Abrechnung auswählen.');}
 else $page=(new \Kulturhus\Verein\CatalogAssignments($db,(string)$_SESSION['actor']))->page($tab,$_GET);
}catch(DomainException $e){$billingError=$e->getMessage();$review=[];}
$route=['view'=>'settings','tab'=>$tab,'billing'=>1];
?>
<link rel="stylesheet" href="catalog-pricing.css">
<section class="card catalog-pricing catalog-billing" id="catalog-billing"><h2 tabindex="-1" autofocus>Tarife abrechnen</h2>
<a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','tab'=>$tab])) ?>">Zum Katalog</a>
<?php if($billingError): ?><p role="alert"><?= e($billingError) ?></p><?php endif ?>
<?php if($ids): ?><details class="catalog-assignment-picker"<?= $billingError?' open':'' ?>><summary>Datum &amp; Berechnung ändern</summary><form method="get" class="form-grid"><?= hidden('view','settings').hidden('tab',$tab).hidden('billing',1).hidden('billing_due',$due) ?><?php foreach($ids as$id)echo hidden('billing_assignments[]',$id); ?><label>Abrechnungsdatum<input class="form-control" type="date" name="billing_date" value="<?= e($day) ?>" max="<?= date('Y-m-d') ?>" required></label><label>Betrag<select class="form-control" name="billing_mode"><option value="full"<?= $mode==='full'?' selected':'' ?>>Voller Tarifbetrag</option><option value="days"<?= $mode==='days'?' selected':'' ?>>Anteilig nach zugewiesenen Tagen</option></select></label><label>Preis-Stichtag (optional)<input class="form-control" type="date" name="billing_day" value="<?= e($priceDay) ?>"></label><button class="btn btn-outline theme-secondary">Prüfung aktualisieren</button></form><a class="btn btn-outline theme-secondary" href="<?= e(url($route)) ?>">Andere Tarife auswählen</a></details><?php endif ?>
<?php if($page): ?>
<form method="get" class="settings-search"><?= hidden('view','settings').hidden('tab',$tab).hidden('billing',1) ?><label>Kontakt oder Tarif<input class="form-control" name="pricing_q" value="<?= e($page['q']) ?>" maxlength="150"></label><button class="btn btn-outline theme-secondary">Suchen</button></form>
<form method="get" class="catalog-billing-select"><?= hidden('view','settings').hidden('tab',$tab).hidden('billing',1).hidden('billing_review',1) ?>
<div class="form-grid"><label>Abrechnungsdatum<input class="form-control" name="billing_date" type="date" value="<?= e($day) ?>" max="<?= date('Y-m-d') ?>" required></label><label>Betrag<select class="form-control" name="billing_mode"><option value="full">Voller Tarifbetrag</option><option value="days">Anteilig nach zugewiesenen Tagen</option></select></label><label>Preis-Stichtag (optional)<input class="form-control" name="billing_day" type="date" value="<?= e($priceDay) ?>"></label></div>
<div class="catalog-assignment-list"><?php foreach($page['rows']as$row):$linked=\Kulturhus\Verein\ContributionRates::linked($db,$billingActor['club_id'],$row['catalog_id']); ?><label class="catalog-assignment billing-choice"><input class="check" type="checkbox" name="billing_assignments[]" value="<?= e($row['id']) ?>"<?= !$row['active']||$linked?' disabled':'' ?>><span><strong><?= e($row['name']) ?></strong><span><?= e($row['catalog_name']) ?></span><small><?= $linked?'Jahresbeitragslauf':(!$row['active']?'Tarif inaktiv':e(dateDe($row['starts_on']).' – '.($row['ends_on']?dateDe($row['ends_on']):'offen'))) ?></small></span></label><?php endforeach ?></div>
<?php if($finance->canWrite()&&$page['rows']): ?><button class="btn btn-solid theme-primary">Auswahl prüfen</button><?php endif ?></form>
<span><?= $page['total'] ?> Zuweisungen · Seite <?= $page['page'] ?> von <?= $page['pages'] ?></span>
<?php if($page['pages']>1): ?><form method="get" class="settings-actions"><?= hidden('view','settings').hidden('tab',$tab).hidden('billing',1).hidden('pricing_q',$page['q']) ?><label>Zuweisungsseite<input class="form-control" type="number" name="pricing_page" min="1" max="<?= $page['pages'] ?>" value="<?= $page['page'] ?>" inputmode="numeric" required></label><button class="btn btn-outline theme-secondary">Seite öffnen</button></form><?php endif ?>
<?php endif ?>
<?php if($review):$blocked=false;$stale=false; ?>
<div class="catalog-assignment-list" data-billing-review><?php foreach($review as$i=>$row):$blocked=$blocked||(bool)$row['charge'];$stale=$stale||($failed&&!hash_equals($oldItems[$i]['fingerprint'],$row['fingerprint'])); ?><article class="catalog-assignment"><div><strong><?= e($row['contact_name'].' · '.$row['name']) ?></strong><span><?= e(euro($row['amount_cents'])) ?> brutto</span><small><?= e(dateDe($row['period_start']).' – '.dateDe($row['period_end'])) ?></small><small><?= e('Preis-Stichtag '.dateDe($row['price_day'])) ?></small><?php if($row['mode']==='days'): ?><small><?= $row['active_days'] ?> von <?= $row['period_days'] ?> Tagen</small><?php endif ?></div><?php if($row['charge']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$row['charge']['entry_id']])) ?>">Bereits abgerechnet · Beleg öffnen</a><?php endif ?></article><?php endforeach ?></div>
<p class="catalog-billing-total"><strong>Gesamt <?= e(euro(array_sum(array_column($review,'amount_cents')))) ?> brutto</strong></p>
<?php if($stale): ?><p role="alert">Preisgrundlage geändert. Neue Abrechnung prüfen.</p><?php endif ?>
<?php if($finance->canWrite()&&!$blocked&&!$stale): ?><form method="post" data-billing-book><?= csrf().hidden('action','catalog-billing-book').hidden('billing_date',$day).hidden('billing_mode',$mode).hidden('billing_day',$priceDay).hidden('billing_key',$key) ?><?php foreach($review as$i=>$row)echo hidden('billing_items['.$i.'][assignment_id]',$row['assignment_id']).hidden('billing_items['.$i.'][fingerprint]',$failed?$oldItems[$i]['fingerprint']:$row['fingerprint']); ?><label>Zahlungsziel<input class="form-control" type="date" name="billing_due" value="<?= e($due) ?>" min="<?= e($day) ?>" required></label><button class="btn btn-solid theme-primary">Jetzt <?= count($review) ?> Tarifbelege anlegen</button></form><?php endif ?>
<?php endif ?>
<?php if($saved): ?><div class="catalog-assignment-list" data-billing-saved><?php foreach($saved as$row):$original=json_decode($row['quote_json'],true,512,JSON_THROW_ON_ERROR); ?><article class="catalog-assignment"><div><strong><?= e($original['contact_name'].' · '.$original['name']) ?></strong><span><?= e(euro($original['amount_cents'])) ?> brutto</span><small><?= e(dateDe($original['period_start']).' – '.dateDe($original['period_end'])) ?></small></div><a class="btn btn-solid theme-primary" href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$row['entry_id']])) ?>">Beleg öffnen</a></article><?php endforeach ?></div><?php endif ?>
<?php if(!$page): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($route+($ids?['billing_assignments'=>$ids,'billing_date'=>$day,'billing_mode'=>$mode,'billing_day'=>$priceDay]:[]))) ?>"><?= $ids?'Neu prüfen':'Neue Abrechnung' ?></a><?php endif ?>
</section>
